package yaml

// Character classification helpers. These mirror the classification used by the
// reference YAML 1.1 emitter that produced the on-disk task files: the notion of
// "printable" deliberately excludes characters outside the basic multilingual
// plane, which is why astral-plane runes end up escaped in double quotes.

// width returns the number of bytes in the UTF-8 sequence starting with b.
func width(b byte) int {
	switch {
	case b&0x80 == 0x00:
		return 1
	case b&0xE0 == 0xC0:
		return 2
	case b&0xF0 == 0xE0:
		return 3
	case b&0xF8 == 0xF0:
		return 4
	}
	return 0
}

func isSpace(b []byte, i int) bool {
	return i < len(b) && b[i] == ' '
}

func isTab(b []byte, i int) bool {
	return i < len(b) && b[i] == '\t'
}

func isBlank(b []byte, i int) bool {
	return isSpace(b, i) || isTab(b, i)
}

// isBreak reports a line break: LF, CR, NEL (U+0085), LS (U+2028) or PS (U+2029).
func isBreak(b []byte, i int) bool {
	if i >= len(b) {
		return false
	}
	switch b[i] {
	case '\r', '\n':
		return true
	case 0xC2:
		return i+1 < len(b) && b[i+1] == 0x85
	case 0xE2:
		return i+2 < len(b) && b[i+1] == 0x80 && (b[i+2] == 0xA8 || b[i+2] == 0xA9)
	}
	return false
}

// isNul mirrors the NUL sentinel of the C implementation; the Go port keeps it
// so that "end of buffer" reads as whitespace.
func isNul(b []byte, i int) bool {
	return i >= len(b) || b[i] == 0
}

func isBreakOrNul(b []byte, i int) bool {
	return isBreak(b, i) || isNul(b, i)
}

func isBlankOrBreakOrNul(b []byte, i int) bool {
	return isBlank(b, i) || isBreakOrNul(b, i)
}

func isASCII(b []byte, i int) bool {
	return i < len(b) && b[i] < 0x80
}

// isPrintable follows the reference emitter's byte-oriented test. Note that a
// leading byte >= 0xF0 (four byte sequence, i.e. U+10000 and above) is *not*
// considered printable, and neither are the C0 controls other than LF.
func isPrintable(b []byte, i int) bool {
	if i >= len(b) {
		return false
	}
	c := b[i]
	switch {
	case c == 0x0A:
		return true
	case c >= 0x20 && c <= 0x7E:
		return true
	case c == 0xC2:
		return i+1 < len(b) && b[i+1] >= 0xA0
	case c > 0xC2 && c < 0xED:
		return true
	case c == 0xED:
		return i+1 < len(b) && b[i+1] < 0xA0
	case c == 0xEE:
		return true
	case c == 0xEF:
		// U+E000..U+FFFD, excluding the BOM and the two non-characters.
		if i+2 >= len(b) {
			return false
		}
		if b[i+1] == 0xBB && b[i+2] == 0xBF {
			return false
		}
		if b[i+1] == 0xBF && (b[i+2] == 0xBE || b[i+2] == 0xBF) {
			return false
		}
		return true
	}
	return false
}

// isBOM reports a UTF-8 encoded byte order mark at i.
func isBOM(b []byte, i int) bool {
	return i+2 < len(b) && b[i] == 0xEF && b[i+1] == 0xBB && b[i+2] == 0xBF
}

