package yaml

// scalarInfo holds the result of analysing a scalar: which presentation styles
// are legal for it, and whether it spans more than one line.
type scalarInfo struct {
	multiline bool

	flowPlainAllowed   bool
	blockPlainAllowed  bool
	singleQuotedAllowed bool
	blockAllowed       bool
}

// analyzeScalar works out which styles may be used to present value. allowUnicode
// is always true for us (the encoder enables it), but it is threaded through so
// the logic stays faithful to the original.
func analyzeScalar(value []byte, allowUnicode bool) scalarInfo {
	if len(value) == 0 {
		return scalarInfo{
			multiline:           false,
			flowPlainAllowed:    false,
			blockPlainAllowed:   true,
			singleQuotedAllowed: true,
			blockAllowed:        false,
		}
	}

	var (
		blockIndicators   bool
		flowIndicators    bool
		lineBreaks        bool
		specialCharacters bool

		leadingSpace  bool
		leadingBreak  bool
		trailingSpace bool
		trailingBreak bool
		breakSpace    bool
		spaceBreak    bool
	)

	precededByWhitespace := true
	followedByWhitespace := len(value) <= 1 || isBlankOrBreakOrNul(value, width(value[0]))
	previousSpace := false
	previousBreak := false

	for i := 0; i < len(value); i += width(value[i]) {
		if i == 0 {
			switch value[i] {
			case '#', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`':
				flowIndicators = true
				blockIndicators = true
			case '?', ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '-':
				if followedByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		} else {
			switch value[i] {
			case ',', '?', '[', ']', '{', '}':
				flowIndicators = true
			case ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '#':
				if precededByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		}

		if !isPrintable(value, i) || (!isASCII(value, i) && !allowUnicode) {
			specialCharacters = true
		}

		switch {
		case isSpace(value, i):
			if i == 0 {
				leadingSpace = true
			}
			if i+width(value[i]) == len(value) {
				trailingSpace = true
			}
			if previousBreak {
				breakSpace = true
			}
			previousSpace = true
			previousBreak = false
		case isBreak(value, i):
			lineBreaks = true
			if i == 0 {
				leadingBreak = true
			}
			if i+width(value[i]) == len(value) {
				trailingBreak = true
			}
			if previousSpace {
				spaceBreak = true
			}
			previousSpace = false
			previousBreak = true
		default:
			previousSpace = false
			previousBreak = false
		}

		precededByWhitespace = isBlankOrBreakOrNul(value, i)
		next := i + width(value[i]) + 1
		followedByWhitespace = next >= len(value) || isBlankOrBreakOrNul(value, next)
	}

	info := scalarInfo{
		multiline:           lineBreaks,
		flowPlainAllowed:    true,
		blockPlainAllowed:   true,
		singleQuotedAllowed: true,
		blockAllowed:        true,
	}

	if leadingSpace || leadingBreak || trailingSpace || trailingBreak {
		info.flowPlainAllowed = false
		info.blockPlainAllowed = false
	}
	if trailingSpace {
		info.blockAllowed = false
	}
	if breakSpace {
		info.flowPlainAllowed = false
		info.blockPlainAllowed = false
		info.singleQuotedAllowed = false
	}
	if spaceBreak || specialCharacters {
		info.flowPlainAllowed = false
		info.blockPlainAllowed = false
		info.singleQuotedAllowed = false
		info.blockAllowed = false
	}
	if lineBreaks {
		info.flowPlainAllowed = false
		info.blockPlainAllowed = false
	}
	if flowIndicators {
		info.flowPlainAllowed = false
	}
	if blockIndicators {
		info.blockPlainAllowed = false
	}

	return info
}

