package yaml

import (
	"regexp"
	"strconv"
	"strings"
	"time"
)

// The emitter must quote any string which, left unquoted, would be re-read as
// something other than a string (a bool, an int, a null, a timestamp...). The
// tables below mirror the YAML 1.1 implicit resolution rules used by the
// reference implementation.

var resolveHint [256]byte

// scalars that resolve to a non-string type by exact match
var resolveExact = map[string]bool{}

func init() {
	resolveHint['+'] = 'S'
	resolveHint['-'] = 'S'
	for _, c := range "0123456789" {
		resolveHint[c] = 'D'
	}
	for _, c := range "yYnNtTfFoO~" {
		resolveHint[c] = 'M'
	}
	resolveHint['.'] = '.'
	resolveHint['<'] = '<'

	groups := [][]string{
		{"y", "Y", "yes", "Yes", "YES", "on", "On", "ON"},
		{"true", "True", "TRUE"},
		{"n", "N", "no", "No", "NO", "off", "Off", "OFF"},
		{"false", "False", "FALSE"},
		{"", "~", "null", "Null", "NULL"},
		{".nan", ".NaN", ".NAN"},
		{".inf", ".Inf", ".INF"},
		{"+.inf", "+.Inf", "+.INF"},
		{"-.inf", "-.Inf", "-.INF"},
		{"<<"},
	}
	for _, g := range groups {
		for _, s := range g {
			resolveExact[s] = true
		}
	}
}

var yamlStyleFloat = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?$`)

var base60float = regexp.MustCompile(`^[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+(?:\.[0-9_]*)?$`)

var timestampFormats = []string{
	"2006-1-2T15:4:5.999999999Z07:00",
	"2006-1-2t15:4:5.999999999Z07:00",
	"2006-1-2 15:4:5.999999999",
	"2006-1-2",
}

func parsesAsTimestamp(s string) bool {
	i := 0
	for ; i < len(s); i++ {
		if c := s[i]; c < '0' || c > '9' {
			break
		}
	}
	if i != 4 || i == len(s) || s[i] != '-' {
		return false
	}
	for _, format := range timestampFormats {
		if _, err := time.Parse(format, s); err == nil {
			return true
		}
	}
	return false
}

// resolvesToString reports whether s read back as a plain scalar would still be
// a string. When it would not, the emitter has to quote it.
func resolvesToString(s string) bool {
	if s == "" {
		return false
	}
	hint := resolveHint[s[0]]
	if hint != 0 {
		if resolveExact[s] {
			return false
		}
		switch hint {
		case 'M', '<':
			// only exact matches, already handled
		case '.':
			if _, err := strconv.ParseFloat(s, 64); err == nil {
				return false
			}
		case 'D', 'S':
			if parsesAsTimestamp(s) {
				return false
			}
			plain := strings.Replace(s, "_", "", -1)
			if _, err := strconv.ParseInt(plain, 0, 64); err == nil {
				return false
			}
			if _, err := strconv.ParseUint(plain, 0, 64); err == nil {
				return false
			}
			if yamlStyleFloat.MatchString(plain) {
				if _, err := strconv.ParseFloat(plain, 64); err == nil {
					return false
				}
			}
			switch {
			case strings.HasPrefix(plain, "0b"):
				if _, err := strconv.ParseInt(plain[2:], 2, 64); err == nil {
					return false
				}
				if _, err := strconv.ParseUint(plain[2:], 2, 64); err == nil {
					return false
				}
			case strings.HasPrefix(plain, "-0b"):
				if _, err := strconv.ParseInt("-"+plain[3:], 2, 64); err == nil {
					return false
				}
			case strings.HasPrefix(plain, "0o"):
				if _, err := strconv.ParseInt(plain[2:], 8, 64); err == nil {
					return false
				}
				if _, err := strconv.ParseUint(plain[2:], 8, 64); err == nil {
					return false
				}
			case strings.HasPrefix(plain, "-0o"):
				if _, err := strconv.ParseInt("-"+plain[3:], 8, 64); err == nil {
					return false
				}
			}
		}
	}
	return true
}

// isBase60Float matches the sexagesimal floats of YAML 1.1. They are not decoded
// but they are still quoted on the way out, for the benefit of other parsers.
func isBase60Float(s string) bool {
	if s == "" {
		return false
	}
	c := s[0]
	if !(c == '+' || c == '-' || (c >= '0' && c <= '9')) || strings.IndexByte(s, ':') < 0 {
		return false
	}
	return base60float.MatchString(s)
}

// canBePlain reports whether a Go string may be emitted as an unquoted scalar as
// far as implicit re-resolution is concerned (style analysis is separate).
func canBePlain(s string) bool {
	return resolvesToString(s) && !isBase60Float(s)
}

