package yaml

import "strings"

// Node is a minimal document model: enough to describe the task documents we
// read and write (a block mapping of scalars and string sequences).
type Node struct {
	Kind  Kind
	Value string // Kind == KindScalar
	Style Style
	Items []*Node
	Pairs []Pair
}

type Pair struct {
	Key string
	Val *Node
}

type Kind int

const (
	KindScalar Kind = iota
	KindSequence
	KindMapping
)

// Style selects how a scalar is presented. StyleAuto reproduces the behaviour of
// marshalling a Go string; StylePlain forces an unquoted scalar, which is what
// marshalling a time.Time does.
type Style int

const (
	StyleAuto Style = iota
	StylePlain
)

func Scalar(v string) *Node       { return &Node{Kind: KindScalar, Value: v} }
func PlainScalar(v string) *Node  { return &Node{Kind: KindScalar, Value: v, Style: StylePlain} }
func Sequence(items ...*Node) *Node {
	return &Node{Kind: KindSequence, Items: items}
}
func Mapping(pairs ...Pair) *Node { return &Node{Kind: KindMapping, Pairs: pairs} }

// internal presentation styles
type scalarStyle int

const (
	stylePlain scalarStyle = iota
	styleSingleQuoted
	styleDoubleQuoted
	styleLiteral
)

type emitter struct {
	out []byte

	column     int
	whitespace bool
	indention  bool

	indent  int
	indents []int

	flowLevel      int
	simpleKey      bool
	mappingContext bool

	bestIndent   int
	bestWidth    int
	allowUnicode bool
}

// Marshal renders a node as a YAML document, matching the byte-for-byte output
// of the reference emitter for the shapes we produce.
func Marshal(n *Node) []byte {
	e := &emitter{
		indent:       -1,
		bestIndent:   2,
		bestWidth:    80,
		allowUnicode: true,
		whitespace:   true,
		indention:    true,
	}
	e.emitNode(n)
	// Document end: ensure the output is newline terminated.
	e.writeIndent()
	return e.out
}

func (e *emitter) put(c byte) {
	e.out = append(e.out, c)
	e.column++
}

func (e *emitter) putBreak() {
	e.out = append(e.out, '\n')
	e.column = 0
}

func (e *emitter) writeAll(s string) {
	for i := 0; i < len(s); {
		e.writeChar([]byte(s), &i)
	}
}

// writeChar copies one (possibly multi-byte) character, counting it as a single
// column.
func (e *emitter) writeChar(b []byte, i *int) {
	w := width(b[*i])
	if w == 0 {
		w = 1
	}
	if *i+w > len(b) {
		w = len(b) - *i
	}
	e.out = append(e.out, b[*i:*i+w]...)
	e.column++
	*i += w
}

func (e *emitter) writeBreakAt(b []byte, i *int) {
	if b[*i] == '\n' {
		e.putBreak()
		*i++
		return
	}
	e.writeChar(b, i)
	e.column = 0
}

func (e *emitter) writeIndent() {
	indent := e.indent
	if indent < 0 {
		indent = 0
	}
	if !e.indention || e.column > indent || (e.column == indent && !e.whitespace) {
		e.putBreak()
	}
	for e.column < indent {
		e.put(' ')
	}
	e.whitespace = true
	e.indention = true
}

func (e *emitter) writeIndicator(indicator string, needWhitespace, isWhitespace, isIndention bool) {
	if needWhitespace && !e.whitespace {
		e.put(' ')
	}
	e.writeAll(indicator)
	e.whitespace = isWhitespace
	e.indention = e.indention && isIndention
}

func (e *emitter) increaseIndent(flow, indentless bool) {
	e.indents = append(e.indents, e.indent)
	if e.indent < 0 {
		if flow {
			e.indent = e.bestIndent
		} else {
			e.indent = 0
		}
	} else if !indentless {
		e.indent += e.bestIndent
	}
}

func (e *emitter) popIndent() {
	e.indent = e.indents[len(e.indents)-1]
	e.indents = e.indents[:len(e.indents)-1]
}

func (e *emitter) emitNode(n *Node) {
	switch n.Kind {
	case KindScalar:
		e.emitScalar(n)
	case KindSequence:
		e.emitSequence(n)
	case KindMapping:
		e.emitMapping(n)
	}
}

func (e *emitter) emitScalar(n *Node) {
	style := e.chooseStyle(n)
	e.increaseIndent(true, false)
	switch style {
	case stylePlain:
		e.writePlainScalar(n.Value, !e.simpleKey)
	case styleSingleQuoted:
		e.writeSingleQuotedScalar(n.Value, !e.simpleKey)
	case styleDoubleQuoted:
		e.writeDoubleQuotedScalar(n.Value, !e.simpleKey)
	case styleLiteral:
		e.writeLiteralScalar(n.Value)
	}
	e.popIndent()
}

func (e *emitter) chooseStyle(n *Node) scalarStyle {
	s := n.Value
	info := analyzeScalar([]byte(s), e.allowUnicode)

	var style scalarStyle
	switch {
	case n.Style == StylePlain:
		style = stylePlain
	case strings.Contains(s, "\n"):
		style = styleLiteral
	case !canBePlain(s):
		style = styleDoubleQuoted
	default:
		style = stylePlain
	}

	if e.simpleKey && info.multiline {
		style = styleDoubleQuoted
	}
	if style == stylePlain {
		if (e.flowLevel > 0 && !info.flowPlainAllowed) || (e.flowLevel == 0 && !info.blockPlainAllowed) {
			style = styleSingleQuoted
		}
		if len(s) == 0 && (e.flowLevel > 0 || e.simpleKey) {
			style = styleSingleQuoted
		}
	}
	if style == styleSingleQuoted && !info.singleQuotedAllowed {
		style = styleDoubleQuoted
	}
	if style == styleLiteral && (!info.blockAllowed || e.flowLevel > 0 || e.simpleKey) {
		style = styleDoubleQuoted
	}
	return style
}

func (e *emitter) emitSequence(n *Node) {
	if len(n.Items) == 0 {
		// Empty sequences are rendered in flow style.
		e.flowLevel++
		e.writeIndicator("[", true, true, false)
		e.writeIndicator("]", false, false, false)
		e.flowLevel--
		return
	}
	indentless := e.mappingContext && !e.indention
	e.increaseIndent(false, indentless)
	savedMapping := e.mappingContext
	for _, item := range n.Items {
		e.writeIndent()
		e.writeIndicator("-", true, false, true)
		e.mappingContext = false
		e.simpleKey = false
		e.emitNode(item)
	}
	e.mappingContext = savedMapping
	e.popIndent()
}

func (e *emitter) emitMapping(n *Node) {
	e.increaseIndent(false, false)
	for _, p := range n.Pairs {
		e.writeIndent()
		// key
		e.mappingContext = true
		e.simpleKey = true
		e.emitScalar(Scalar(p.Key))
		e.simpleKey = false
		// ": "
		e.writeIndicator(":", false, false, false)
		e.mappingContext = true
		e.emitNode(p.Val)
	}
	e.mappingContext = false
	e.popIndent()
}

func (e *emitter) writePlainScalar(value string, allowBreaks bool) {
	if len(value) > 0 && !e.whitespace {
		e.put(' ')
	}
	b := []byte(value)
	spaces := false
	breaks := false
	for i := 0; i < len(b); {
		switch {
		case isSpace(b, i):
			if allowBreaks && !spaces && e.column > e.bestWidth && !isSpace(b, i+1) {
				e.writeIndent()
				i += width(b[i])
			} else {
				e.writeChar(b, &i)
			}
			spaces = true
		case isBreak(b, i):
			if !breaks && b[i] == '\n' {
				e.putBreak()
			}
			e.writeBreakAt(b, &i)
			e.indention = true
			breaks = true
		default:
			if breaks {
				e.writeIndent()
			}
			e.writeChar(b, &i)
			e.indention = false
			breaks = false
			spaces = false
		}
	}
	e.whitespace = false
	e.indention = false
}

func (e *emitter) writeSingleQuotedScalar(value string, allowBreaks bool) {
	e.writeIndicator("'", true, false, false)
	b := []byte(value)
	spaces := false
	breaks := false
	for i := 0; i < len(b); {
		switch {
		case isSpace(b, i):
			if allowBreaks && !spaces && e.column > e.bestWidth && i > 0 && i < len(b)-1 && !isSpace(b, i+1) {
				e.writeIndent()
				i += width(b[i])
			} else {
				e.writeChar(b, &i)
			}
			spaces = true
		case isBreak(b, i):
			if !breaks && b[i] == '\n' {
				e.putBreak()
			}
			e.writeBreakAt(b, &i)
			e.indention = true
			breaks = true
		default:
			if breaks {
				e.writeIndent()
			}
			if b[i] == '\'' {
				e.put('\'')
				e.put('\'')
				i++
			} else {
				e.writeChar(b, &i)
			}
			e.indention = false
			breaks = false
			spaces = false
		}
	}
	if breaks {
		e.writeIndent()
	}
	e.writeIndicator("'", false, false, false)
	e.whitespace = false
	e.indention = false
}

func (e *emitter) writeDoubleQuotedScalar(value string, allowBreaks bool) {
	e.writeIndicator("\"", true, false, false)
	b := []byte(value)
	spaces := false
	for i := 0; i < len(b); {
		if !isPrintable(b, i) || (!e.allowUnicode && !isASCII(b, i)) ||
			isBOM(b, i) || isBreak(b, i) || b[i] == '"' || b[i] == '\\' {

			octet := b[i]
			var w int
			var v rune
			switch {
			case octet&0x80 == 0x00:
				w, v = 1, rune(octet&0x7F)
			case octet&0xE0 == 0xC0:
				w, v = 2, rune(octet&0x1F)
			case octet&0xF0 == 0xE0:
				w, v = 3, rune(octet&0x0F)
			case octet&0xF8 == 0xF0:
				w, v = 4, rune(octet&0x07)
			default:
				w, v = 1, rune(octet)
			}
			for k := 1; k < w && i+k < len(b); k++ {
				v = (v << 6) + (rune(b[i+k]) & 0x3F)
			}
			i += w

			e.put('\\')
			switch v {
			case 0x00:
				e.put('0')
			case 0x07:
				e.put('a')
			case 0x08:
				e.put('b')
			case 0x09:
				e.put('t')
			case 0x0A:
				e.put('n')
			case 0x0B:
				e.put('v')
			case 0x0C:
				e.put('f')
			case 0x0D:
				e.put('r')
			case 0x1B:
				e.put('e')
			case 0x22:
				e.put('"')
			case 0x5C:
				e.put('\\')
			case 0x85:
				e.put('N')
			case 0xA0:
				e.put('_')
			case 0x2028:
				e.put('L')
			case 0x2029:
				e.put('P')
			default:
				var digits int
				switch {
				case v <= 0xFF:
					e.put('x')
					digits = 2
				case v <= 0xFFFF:
					e.put('u')
					digits = 4
				default:
					e.put('U')
					digits = 8
				}
				for k := (digits - 1) * 4; k >= 0; k -= 4 {
					d := byte((v >> uint(k)) & 0x0F)
					if d < 10 {
						e.put(d + '0')
					} else {
						e.put(d + 'A' - 10)
					}
				}
			}
			spaces = false
		} else if isSpace(b, i) {
			if allowBreaks && !spaces && e.column > e.bestWidth && i > 0 && i < len(b)-1 {
				e.writeIndent()
				if isSpace(b, i+1) {
					e.put('\\')
				}
				i += width(b[i])
			} else {
				e.writeChar(b, &i)
			}
			spaces = true
		} else {
			e.writeChar(b, &i)
			spaces = false
		}
	}
	e.writeIndicator("\"", false, false, false)
	e.whitespace = false
	e.indention = false
}

func (e *emitter) writeLiteralScalar(value string) {
	b := []byte(value)
	breaks := true
	e.writeIndicator("|", true, false, false)
	e.writeBlockScalarHints(b)
	e.putBreak()
	e.indention = true
	e.whitespace = true
	for i := 0; i < len(b); {
		if isBreak(b, i) {
			e.writeBreakAt(b, &i)
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			e.writeChar(b, &i)
			e.indention = false
			breaks = false
		}
	}
}

func (e *emitter) writeBlockScalarHints(b []byte) {
	if isSpace(b, 0) || isBreak(b, 0) {
		e.writeIndicator(string([]byte{'0' + byte(e.bestIndent)}), false, false, false)
	}
	var chomp byte
	if len(b) == 0 {
		chomp = '-'
	} else {
		i := len(b) - 1
		for i > 0 && b[i]&0xC0 == 0x80 {
			i--
		}
		if !isBreak(b, i) {
			chomp = '-'
		} else if i == 0 {
			chomp = '+'
		} else {
			i--
			for i > 0 && b[i]&0xC0 == 0x80 {
				i--
			}
			if isBreak(b, i) {
				chomp = '+'
			}
		}
	}
	if chomp != 0 {
		e.writeIndicator(string([]byte{chomp}), false, false, false)
	}
}

