		e.emitNode(p.Val)
	}
	e.mappingContext = false
	e.popIndent()
}

func (e *emitter) writePlainScalar(value string, allowBreaks bool) {
	if len(value) > 0 && !e.whitespace {
		e.put(' ')
	}
	b := []byte(value)
	spaces := false
	breaks := false
	for i := 0; i < len(b); {
		switch {
		case isSpace(b, i):
			if allowBreaks && !spaces && e.column > e.bestWidth && !isSpace(b, i+1) {
				e.writeIndent()
				i += width(b[i])
			} else {
				e.writeChar(b, &i)
			}
			spaces = true
		case isBreak(b, i):
			if !breaks && b[i] == '\n' {
				e.putBreak()
			}
			e.writeBreakAt(b, &i)
			e.indention = true
			breaks = true
		default:
			if breaks {
				e.writeIndent()
			}
			e.writeChar(b, &i)
			e.indention = false
			breaks = false
			spaces = false
		}
	}
	e.whitespace = false
	e.indention = false
}

func (e *emitter) writeSingleQuotedScalar(value string, allowBreaks bool) {
	e.writeIndicator("'", true, false, false)
	b := []byte(value)
	spaces := false
	breaks := false
	for i := 0; i < len(b); {
		switch {
		case isSpace(b, i):
			if allowBreaks && !spaces && e.column > e.bestWidth && i > 0 && i < len(b)-1 && !isSpace(b, i+1) {
				e.writeIndent()
				i += width(b[i])
			} else {
				e.writeChar(b, &i)
			}
			spaces = true
		case isBreak(b, i):
			if !breaks && b[i] == '\n' {
				e.putBreak()
			}
			e.writeBreakAt(b, &i)
			e.indention = true
			breaks = true
		default:
			if breaks {
				e.writeIndent()
			}
			if b[i] == '\'' {
				e.put('\'')
				e.put('\'')
				i++
			} else {
				e.writeChar(b, &i)
			}
			e.indention = false
			breaks = false
			spaces = false
		}
	}
	if breaks {
		e.writeIndent()
	}
	e.writeIndicator("'", false, false, false)
	e.whitespace = false
	e.indention = false
}

func (e *emitter) writeDoubleQuotedScalar(value string, allowBreaks bool) {
	e.writeIndicator("\"", true, false, false)
	b := []byte(value)
	spaces := false
	for i := 0; i < len(b); {
		if !isPrintable(b, i) || (!e.allowUnicode && !isASCII(b, i)) ||
			isBOM(b, i) || isBreak(b, i) || b[i] == '"' || b[i] == '\\' {

			octet := b[i]
			var w int
			var v rune
			switch {
			case octet&0x80 == 0x00:
				w, v = 1, rune(octet&0x7F)
			case octet&0xE0 == 0xC0:
				w, v = 2, rune(octet&0x1F)
			case octet&0xF0 == 0xE0:
				w, v = 3, rune(octet&0x0F)
			case octet&0xF8 == 0xF0:
				w, v = 4, rune(octet&0x07)
			default:
				w, v = 1, rune(octet)
			}
			for k := 1; k < w && i+k < len(b); k++ {
				v = (v << 6) + (rune(b[i+k]) & 0x3F)
			}
			i += w

			e.put('\\')
			switch v {
			case 0x00:
				e.put('0')
			case 0x07:
				e.put('a')
			case 0x08:
				e.put('b')
			case 0x09:
				e.put('t')
			case 0x0A:
				e.put('n')
			case 0x0B:
				e.put('v')
			case 0x0C:
				e.put('f')
			case 0x0D:
				e.put('r')
			case 0x1B:
				e.put('e')
			case 0x22:
				e.put('"')
			case 0x5C:
				e.put('\\')
			case 0x85:
				e.put('N')
			case 0xA0:
				e.put('_')
			case 0x2028:
				e.put('L')
			case 0x2029:
				e.put('P')
			default:
				var digits int
				switch {
				case v <= 0xFF:
					e.put('x')
					digits = 2
				case v <= 0xFFFF:
					e.put('u')
					digits = 4
				default:
					e.put('U')
					digits = 8
				}
				for k := (digits - 1) * 4; k >= 0; k -= 4 {
					d := byte((v >> uint(k)) & 0x0F)
					if d < 10 {
						e.put(d + '0')
					} else {
						e.put(d + 'A' - 10)
					}
				}
			}
			spaces = false
		} else if isSpace(b, i) {
			if allowBreaks && !spaces && e.column > e.bestWidth && i > 0 && i < len(b)-1 {
				e.writeIndent()
				if isSpace(b, i+1) {
					e.put('\\')
				}
				i += width(b[i])
			} else {
				e.writeChar(b, &i)
			}
			spaces = true
		} else {
			e.writeChar(b, &i)
			spaces = false
		}
	}
	e.writeIndicator("\"", false, false, false)
	e.whitespace = false
	e.indention = false
}

func (e *emitter) writeLiteralScalar(value string) {
	b := []byte(value)
	breaks := true
	e.writeIndicator("|", true, false, false)
	e.writeBlockScalarHints(b)
	e.putBreak()
	e.indention = true
	e.whitespace = true
	for i := 0; i < len(b); {
		if isBreak(b, i) {
			e.writeBreakAt(b, &i)
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			e.writeChar(b, &i)
			e.indention = false
			breaks = false
		}
	}
}

func (e *emitter) writeBlockScalarHints(b []byte) {
	if isSpace(b, 0) || isBreak(b, 0) {
		e.writeIndicator(string([]byte{'0' + byte(e.bestIndent)}), false, false, false)
	}
	var chomp byte
	if len(b) == 0 {
		chomp = '-'
	} else {
		i := len(b) - 1
		for i > 0 && b[i]&0xC0 == 0x80 {
			i--
		}
		if !isBreak(b, i) {
			chomp = '-'
		} else if i == 0 {
			chomp = '+'
		} else {
			i--
			for i > 0 && b[i]&0xC0 == 0x80 {
				i--
			}
			if isBreak(b, i) {
				chomp = '+'
			}
		}
	}
	if chomp != 0 {
		e.writeIndicator(string([]byte{chomp}), false, false, false)
	}
}

