package yaml

import (
	"fmt"
	"strconv"
	"strings"
)

// Unmarshal parses a block-style YAML document into a Node tree. It covers the
// subset needed for task files: a top level mapping whose values are scalars
// (plain, quoted, or block) and sequences of scalars.
func Unmarshal(data []byte) (*Node, error) {
	p := &parser{lines: splitLines(string(data))}
	return p.parseDocument()
}

type line struct {
	indent  int    // number of leading spaces
	content string // text after the indent, with trailing CR removed
	raw     string
	blank   bool
	comment bool
	num     int
}

func splitLines(s string) []line {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	parts := strings.Split(s, "\n")
	// A trailing newline yields a final empty element; drop it.
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	out := make([]line, 0, len(parts))
	for i, p := range parts {
		indent := 0
		for indent < len(p) && p[indent] == ' ' {
			indent++
		}
		content := p[indent:]
		out = append(out, line{
			indent:  indent,
			content: content,
			raw:     p,
			blank:   strings.TrimSpace(p) == "",
			comment: strings.HasPrefix(content, "#"),
			num:     i + 1,
		})
	}
	return out
}

type parser struct {
	lines []line
	pos   int
}

func (p *parser) errf(format string, args ...interface{}) error {
	return fmt.Errorf("yaml: "+format, args...)
}

func (p *parser) skipIgnorable() {
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.blank || l.comment || l.content == "---" || l.content == "..." {
			p.pos++
			continue
		}
		return
	}
}

func (p *parser) parseDocument() (*Node, error) {
	p.skipIgnorable()
	if p.pos >= len(p.lines) {
		return &Node{Kind: KindMapping}, nil
	}
	l := p.lines[p.pos]
	if strings.HasPrefix(l.content, "- ") || l.content == "-" {
		return p.parseSequence(l.indent)
	}
	return p.parseMapping(l.indent)
}

func (p *parser) parseMapping(indent int) (*Node, error) {
	m := &Node{Kind: KindMapping}
	for {
		p.skipIgnorable()
		if p.pos >= len(p.lines) {
			break
		}
		l := p.lines[p.pos]
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			return nil, p.errf("line %d: mapping values are not allowed in this context", l.num)
		}
		key, rest, err := splitKey(l.content)
		if err != nil {
			return nil, p.errf("line %d: %v", l.num, err)
		}
		p.pos++
		val, err := p.parseValue(indent, rest, l.num)
		if err != nil {
			return nil, err
		}
		m.Pairs = append(m.Pairs, Pair{Key: key, Val: val})
	}
	return m, nil
}

// splitKey separates "key:" / "key: value" into its parts.
func splitKey(s string) (key, rest string, err error) {
	if strings.HasPrefix(s, "\"") || strings.HasPrefix(s, "'") {
		q := s[0]
		i := 1
		var sb strings.Builder
		for i < len(s) {
			if s[i] == q {
				if q == '\'' && i+1 < len(s) && s[i+1] == '\'' {
					sb.WriteByte('\'')
					i += 2
					continue
				}
				i++
				break
			}
			if q == '"' && s[i] == '\\' && i+1 < len(s) {
				sb.WriteByte(s[i])
				sb.WriteByte(s[i+1])
				i += 2
				continue
			}
			sb.WriteByte(s[i])
			i++
		}
		raw := sb.String()
		if q == '"' {
			raw = unescapeDouble(raw)
		}
		for i < len(s) && s[i] == ' ' {
			i++
		}
		if i >= len(s) || s[i] != ':' {
			return "", "", fmt.Errorf("could not find expected ':'")
		}
		return raw, strings.TrimLeft(s[i+1:], " "), nil
	}
	// find the first ": " or a trailing ":"
	for i := 0; i < len(s); i++ {
		if s[i] != ':' {
			continue
		}
		if i+1 == len(s) {
			return s[:i], "", nil
		}
		if s[i+1] == ' ' {
			return s[:i], strings.TrimLeft(s[i+1:], " "), nil
		}
	}
	return "", "", fmt.Errorf("could not find expected ':'")
}

func (p *parser) parseValue(parentIndent int, inline string, lineNum int) (*Node, error) {
	inline = stripTrailingComment(inline)
	if inline != "" {
		switch inline[0] {
		case '|', '>':
			return p.parseBlockScalar(parentIndent, inline)
		case '[':
			return parseFlowSequence(inline)
		case '{':
			return &Node{Kind: KindMapping}, nil
		}
		s, err := p.parseInlineScalar(inline, parentIndent)
		if err != nil {
			return nil, p.errf("line %d: %v", lineNum, err)
		}
		return Scalar(s), nil
	}
	// value lives on the following lines
	p.skipIgnorable()
	if p.pos >= len(p.lines) {
		return Scalar(""), nil
	}
	l := p.lines[p.pos]
	switch {
	case l.indent < parentIndent:
		return Scalar(""), nil
	case l.indent == parentIndent && (strings.HasPrefix(l.content, "- ") || l.content == "-"):
		return p.parseSequence(l.indent)
	case l.indent <= parentIndent:
		return Scalar(""), nil
	case strings.HasPrefix(l.content, "- ") || l.content == "-":
		return p.parseSequence(l.indent)
	default:
		return p.parseMapping(l.indent)
	}
}

func (p *parser) parseSequence(indent int) (*Node, error) {
	seq := &Node{Kind: KindSequence, Items: []*Node{}}
	for {
		p.skipIgnorable()
		if p.pos >= len(p.lines) {
			break
		}
		l := p.lines[p.pos]
		if l.indent != indent {
			break
		}
		if !strings.HasPrefix(l.content, "- ") && l.content != "-" {
			break
		}
		item := strings.TrimSpace(strings.TrimPrefix(l.content, "-"))
		p.pos++
		item = stripTrailingComment(item)
		if item == "" {
			seq.Items = append(seq.Items, Scalar(""))
			continue
		}
		s, err := p.parseInlineScalar(item, indent)
		if err != nil {
			return nil, p.errf("line %d: %v", l.num, err)
		}
		seq.Items = append(seq.Items, Scalar(s))
	}
	return seq, nil
}

// parseInlineScalar handles a scalar that starts on the current line. Plain
// scalars may continue over following, more-indented lines (folded).
func (p *parser) parseInlineScalar(s string, parentIndent int) (string, error) {
	switch s[0] {
	case '\'':
		return p.parseQuoted(s, '\'', parentIndent)
	case '"':
		return p.parseQuoted(s, '"', parentIndent)
	}
	// plain: gather continuation lines
	parts := []string{strings.TrimRight(s, " ")}
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.blank {
			// a blank line inside a plain scalar becomes a newline; only
			// continue if a more indented line follows
			j := p.pos
			for j < len(p.lines) && p.lines[j].blank {
				j++
			}
			if j < len(p.lines) && p.lines[j].indent > parentIndent && !isKeyLine(p.lines[j].content) {
				breaks := j - p.pos
				p.pos = j
				sep := strings.Repeat("\n", breaks)
				parts = append(parts, sep+strings.TrimRight(p.lines[j].content, " "))
				p.pos++
				continue
			}
			break
		}
		if l.indent <= parentIndent || l.comment {
			break
		}
		if isKeyLine(l.content) {
			break
		}
		parts = append(parts, strings.TrimRight(stripTrailingComment(l.content), " "))
		p.pos++
	}
	if len(parts) == 1 {
		return parts[0], nil
	}
	var sb strings.Builder
	sb.WriteString(parts[0])
	for _, part := range parts[1:] {
		if strings.HasPrefix(part, "\n") {
			// N blank lines fold to N newlines
			n := 0
			for n < len(part) && part[n] == '\n' {
				n++
			}
			sb.WriteString(strings.Repeat("\n", n))
			sb.WriteString(part[n:])
		} else {
			sb.WriteString(" ")
			sb.WriteString(part)
		}
	}
	return sb.String(), nil
}

func isKeyLine(s string) bool {
	_, _, err := splitKey(s)
	return err == nil
}

func (p *parser) parseQuoted(s string, q byte, parentIndent int) (string, error) {
	var sb strings.Builder
	cur := s[1:]
	for {
		i := 0
		closed := false
		for i < len(cur) {
			c := cur[i]
			if c == q {
				if q == '\'' && i+1 < len(cur) && cur[i+1] == '\'' {
					sb.WriteByte('\'')
					i += 2
					continue
				}
				closed = true
				i++
				break
			}
			if q == '"' && c == '\\' && i+1 < len(cur) {
				sb.WriteByte(c)
				sb.WriteByte(cur[i+1])
				i += 2
				continue
			}
			sb.WriteByte(c)
			i++
		}
		if closed {
			break
		}
		// continue on the next line, folding the break into a space
		if p.pos >= len(p.lines) {
			return "", fmt.Errorf("found unexpected end of stream")
		}
		l := p.lines[p.pos]
		p.pos++
		trimmed := strings.TrimRight(sb.String(), " ")
		sb.Reset()
		sb.WriteString(trimmed)
		if l.blank {
			sb.WriteString("\n")
			cur = ""
			continue
		}
		sb.WriteString(" ")
		cur = strings.TrimRight(l.content, " ")
	}
	out := sb.String()
	if q == '"' {
		out = unescapeDouble(out)
	}
	return out, nil
}

func unescapeDouble(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); {
		if s[i] != '\\' || i+1 >= len(s) {
			sb.WriteByte(s[i])
			i++
			continue
		}
		c := s[i+1]
		i += 2
		switch c {
		case '0':
			sb.WriteByte(0)
		case 'a':
			sb.WriteByte(7)
		case 'b':
			sb.WriteByte(8)
		case 't', '\t':
			sb.WriteByte('\t')
		case 'n':
			sb.WriteByte('\n')
		case 'v':
			sb.WriteByte(11)
		case 'f':
			sb.WriteByte(12)
		case 'r':
			sb.WriteByte('\r')
		case 'e':
			sb.WriteByte(27)
		case ' ':
			sb.WriteByte(' ')
		case '"':
			sb.WriteByte('"')
		case '/':
			sb.WriteByte('/')
		case '\\':
			sb.WriteByte('\\')
		case 'N':
			sb.WriteString("")
		case '_':
			sb.WriteString(" ")
		case 'L':
			sb.WriteString(" ")
		case 'P':
			sb.WriteString(" ")
		case 'x', 'u', 'U':
			n := 2
			if c == 'u' {
				n = 4
			} else if c == 'U' {
				n = 8
			}
			if i+n <= len(s) {
				if v, err := strconv.ParseUint(s[i:i+n], 16, 32); err == nil {
					sb.WriteRune(rune(v))
					i += n
					continue
				}
			}
			sb.WriteByte('\\')
			sb.WriteByte(c)
		default:
			sb.WriteByte('\\')
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

func (p *parser) parseBlockScalar(parentIndent int, header string) (*Node, error) {
	literal := header[0] == '|'
	chomp := byte(0) // 0 = clip, '-' = strip, '+' = keep
	explicitIndent := 0
	for _, c := range header[1:] {
		switch {
		case c == '-' || c == '+':
			chomp = byte(c)
		case c >= '1' && c <= '9':
			explicitIndent = int(c - '0')
		}
	}

	// Determine the block indentation: the indent of the first non-empty line.
	blockIndent := 0
	if explicitIndent > 0 {
		blockIndent = parentIndent + explicitIndent
	} else {
		for i := p.pos; i < len(p.lines); i++ {
			if p.lines[i].blank {
				continue
			}
			blockIndent = p.lines[i].indent
			break
		}
		if blockIndent <= parentIndent {
			blockIndent = parentIndent + 1
		}
	}

	var content []string
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.blank {
			// Blank lines belong to the block if any further content follows.
			j := p.pos
			for j < len(p.lines) && p.lines[j].blank {
				j++
			}
			if j < len(p.lines) && p.lines[j].indent >= blockIndent {
				for k := p.pos; k < j; k++ {
					content = append(content, trimBlockIndent(p.lines[k].raw, blockIndent))
				}
				p.pos = j
				continue
			}
			break
		}
		if l.indent < blockIndent {
			break
		}
		content = append(content, trimBlockIndent(l.raw, blockIndent))
		p.pos++
	}

	var out string
	if literal {
		if len(content) > 0 {
			out = strings.Join(content, "\n") + "\n"
		}
	} else {
		out = foldLines(content)
	}
	// chomping
	switch chomp {
	case '-':
		out = strings.TrimRight(out, "\n")
	case '+':
		// keep as-is (trailing blank lines already captured)
	default:
		out = strings.TrimRight(out, "\n")
		if len(content) > 0 {
			out += "\n"
		}
	}
	return &Node{Kind: KindScalar, Value: out}, nil
}

func trimBlockIndent(raw string, indent int) string {
	if len(raw) <= indent {
		return ""
	}
	return raw[indent:]
}

func foldLines(content []string) string {
	var sb strings.Builder
	for i, l := range content {
		if i == 0 {
			sb.WriteString(l)
			continue
		}
		if l == "" || content[i-1] == "" || strings.HasPrefix(l, " ") {
			sb.WriteString("\n")
			sb.WriteString(l)
			continue
		}
		sb.WriteString(" ")
		sb.WriteString(l)
	}
	if sb.Len() > 0 {
		sb.WriteString("\n")
	}
	return sb.String()
}

func parseFlowSequence(s string) (*Node, error) {
	inner := strings.TrimSpace(s)
	if !strings.HasPrefix(inner, "[") {
		return nil, fmt.Errorf("yaml: expected flow sequence")
	}
	end := strings.LastIndex(inner, "]")
	if end < 0 {
		return nil, fmt.Errorf("yaml: unterminated flow sequence")
	}
	inner = inner[1:end]
	seq := &Node{Kind: KindSequence, Items: []*Node{}}
	if strings.TrimSpace(inner) == "" {
		return seq, nil
	}
	for _, part := range splitFlowItems(inner) {
		part = strings.TrimSpace(part)
		if len(part) >= 2 && (part[0] == '\'' || part[0] == '"') && part[len(part)-1] == part[0] {
			q := part[0]
			body := part[1 : len(part)-1]
			if q == '\'' {
				body = strings.ReplaceAll(body, "''", "'")
			} else {
				body = unescapeDouble(body)
			}
			seq.Items = append(seq.Items, Scalar(body))
			continue
		}
		seq.Items = append(seq.Items, Scalar(part))
	}
	return seq, nil
}

func splitFlowItems(s string) []string {
	var out []string
	depth := 0
	var quote byte
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote != 0 {
			if c == quote {
				quote = 0
			}
			continue
		}
		switch c {
		case '\'', '"':
			quote = c
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case ',':
			if depth == 0 {
				out = append(out, s[start:i])
				start = i + 1
			}
		}
	}
	out = append(out, s[start:])
	return out
}

func stripTrailingComment(s string) string {
	if strings.HasPrefix(s, "#") {
		return ""
	}
	var quote byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote != 0 {
			if c == quote {
				quote = 0
			}
			continue
		}
		switch c {
		case '\'', '"':
			quote = c
		case '#':
			if i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') {
				return strings.TrimRight(s[:i], " \t")
			}
		}
	}
	return s
}

// Get returns the value node for key, or nil.
func (n *Node) Get(key string) *Node {
	if n == nil || n.Kind != KindMapping {
		return nil
	}
	for _, p := range n.Pairs {
		if p.Key == key {
			return p.Val
		}
	}
	return nil
}

// Str returns the scalar text of the value at key.
func (n *Node) Str(key string) string {
	v := n.Get(key)
	if v == nil || v.Kind != KindScalar {
		return ""
	}
	return v.Value
}

// Strings returns the sequence at key as a slice of scalars.
func (n *Node) Strings(key string) []string {
	v := n.Get(key)
	if v == nil {
		return nil
	}
	if v.Kind == KindScalar {
		if v.Value == "" {
			return nil
		}
		return []string{v.Value}
	}
	if v.Kind != KindSequence {
		return nil
	}
	out := make([]string, 0, len(v.Items))
	for _, it := range v.Items {
		out = append(out, it.Value)
	}
	return out
}

