package yaml

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// TestAgainstReference is a differential test: it asks the reference dstask
// binary to rewrite a set of task files and checks that our emitter produces
// byte-identical output. It only runs when DSTASK_REF points at a binary.
//
//	DSTASK_REF=/path/to/dstask go test ./internal/yaml/ -run Reference -v
func TestAgainstReference(t *testing.T) {
	ref := os.Getenv("DSTASK_REF")
	if ref == "" {
		t.Skip("DSTASK_REF not set")
	}

	values := referenceCorpus()

	dir := t.TempDir()
	repo := filepath.Join(dir, "repo")
	if err := os.MkdirAll(filepath.Join(repo, "pending"), 0o700); err != nil {
		t.Fatal(err)
	}
	run(t, dir, "git", "init", "-q", repo)
	run(t, repo, "git", "config", "user.email", "t@t")
	run(t, repo, "git", "config", "user.name", "T")

	type probe struct {
		uuid    string
		summary string
		notes   string
		project string
	}
	var probes []probe
	for i, v := range values {
		p := probe{
			uuid:    fmt.Sprintf("aaaaaaaa-0000-4000-8000-%012d", i+1),
			summary: v.summary,
			notes:   v.notes,
			project: v.project,
		}
		probes = append(probes, p)
		doc := "summary: " + dq(p.summary) + "\n" +
			"notes: " + dq(p.notes) + "\n" +
			"tags: []\n" +
			"project: " + dq(p.project) + "\n" +
			"priority: P2\n" +
			"delegatedto: \"\"\n" +
			"subtasks: []\n" +
			"dependencies: []\n" +
			"created: 2026-01-01T00:00:00Z\n" +
			"resolved: 0001-01-01T00:00:00Z\n" +
			"due: 0001-01-01T00:00:00Z\n"
		if err := os.WriteFile(filepath.Join(repo, "pending", p.uuid+".yml"), []byte(doc), 0o600); err != nil {
			t.Fatal(err)
		}
	}
